What does this Observer design pattern implementation demonstrate?

class Subject {
    private String state = "";
    private Observer observer;

    public void attach(Observer o) { observer = o; }
    public void setState(String s) { 
        state = s;
        if (observer != null) observer.update(state);
    }
}

class Observer {
    private String name;
    public Observer(String n) { name = n; }
    public void update(String state) {
        System.out.println(name + " notified: " + state);
    }
}

public class Main {
    public static void main(String[] args) {
        Subject s = new Subject();
        Observer o = new Observer("Watcher");
        s.attach(o);
        s.setState("Active");
    }
}

